SELECT
    ,
    sp.supplier_name AS supplierName,
    st.store_name AS storeName,
    eu.nickname AS userName


    p.is_deleted = 0


        AND (p.purchase_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.remark LIKE CONCAT('%', #{q.keyword}, '%')
        OR sp.supplier_name LIKE CONCAT('%', #{q.keyword}, '%'))


        AND p.supplier_id = #{q.supplierId}


        AND p.status = #{q.status}



        AND p.user_id = #{q.userId}


        AND p.create_time >= #{q.beginTime}


        AND p.create_time <= #{q.endTime}



ORDER BY p.id DESC
